As a counterpoint example that leverages the existing AI sdk telemetry. This works almost completely except for a few rough edges:

- sessionID isn't set on spans but that could be done by simply setting it on the active span context.
- There are also some discrepancies between what ai-sdk names various attributes and what the otel gen_ai vendors expect (e.g. langfuse, langsmith, arize, brainstrust etc.) Could be solved either with upstream fixes or a custom span processor.

```opencode.json
  "experimental": {
    "openTelemetry": true
  }
 ```
 
 ```opencode/plugin/otel.ts
 import type { Plugin } from "@opencode-ai/plugin";
import { resourceFromAttributes } from "@opentelemetry/resources";
import { NodeSDK } from "@opentelemetry/sdk-node";
import { ATTR_SERVICE_NAME } from "@opentelemetry/semantic-conventions";

const { trace } = await import("@opentelemetry/api");

export const MyPlugin: Plugin = async ({
  project,
  client,
  $,
  directory,
  worktree,
}) => {
 
  const exporter = new OTLPTraceExporter({
     url: "http://localhost:3000/api/public/otel",
     headers: {
       Authorization: `Basic ${key}`,
     },
  });
  const processor = new BatchSpanProcessor(exporter);
  const processorConsole = new SimpleSpanProcessor(new ConsoleSpanExporter());

  const sdk = new NodeSDK({
    resource: resourceFromAttributes({
      [ATTR_SERVICE_NAME]: "opencode",
    }),
    spanProcessors: [
        processor,
        // Uncomment for dev-debugging
        // processorConsole
    ],
  });

  sdk.start();

  // Ensure spans are flushed on process exit.
  const shutdown = async () => {
    await sdk.shutdown();
  };
  process.on("beforeExit", shutdown);
  process.on("SIGINT", shutdown);
  process.on("SIGTERM", shutdown);

  return {
    event: async ({ event }) => {
      // NOTE: this does NOT work because the events are fired async so the context
      // doesn't actually get attached on the the spans of iterest.
      // if (event.type === "session.created") {
      //  const span = trace.getActiveSpan();
      //  if (span) {
      //    span.setAttribute("session.id", event.properties.info.id);
      //  }
      // }
    },
  };
};
